What is the output of the following program?

#include <stdio.h>
#include <stdlib.h>
void alloc(int *p) {
    p = malloc(sizeof(int));
}
int main(void) {
    int *q = NULL;
    alloc(q);
    printf("%s", q == NULL ? "NULL" : "allocated");
    return 0;
}

Assume every allocation succeeds. What is the output of the following program?

#include <stdio.h>
#include <stdlib.h>
void grow(int **pp, int n) {
    *pp = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) (*pp)[i] = i * 3;
}
int main(void) {
    int *a = NULL;
    grow(&a, 4);
    printf("%d %d", a[1] + a[3], a[2]);
    free(a);
    return 0;
}

